from itertools import combinations, permutations
from test_reduce import solve_hamiltonian_path, solve_hamiltonian_cycle, all_graphs

def perm_path(inst):
    n=inst["n"]; E={frozenset(e) for e in inst["edges"]}
    if n==0: return False
    if n==1: return True
    for p in permutations(range(n)):
        if all(frozenset((p[i],p[i+1])) in E for i in range(n-1)): return True
    return False

def perm_cycle(inst):
    n=inst["n"]; E={frozenset(e) for e in inst["edges"]}
    if n<=2: return False
    for p in permutations(range(1,n)):
        c=(0,)+p
        if all(frozenset((c[i],c[(i+1)%n])) in E for i in range(n)): return True
    return False

bad=0; cnt=0
for n in range(0,7):
    for inst in all_graphs(n):
        cnt+=1
        if solve_hamiltonian_path(inst)!=perm_path(inst): bad+=1; print("PATH MISMATCH",inst)
        if solve_hamiltonian_cycle(inst)!=perm_cycle(inst): bad+=1; print("CYCLE MISMATCH",inst)
print("cross-checked",cnt,"graphs, mismatches:",bad)

# polynomial-time check: large n
import time, random
random.seed(1)
for n in [1000, 5000, 20000]:
    edges=[[i,i+1] for i in range(n-1)]
    inst={"n":n,"edges":edges}
    t=time.time(); out=__import__("reduce").reduce(inst); dt=time.time()-t
    print(f"n={n} reduce time={dt:.4f}s out_n={out['n']} out_edges={len(out['edges'])}")
EOF"}

